<script lang="ts">let { tabs = [], value = $bindable('') }: { tabs?: { id: string; label: string }[]; value?: string } = $props();</script><div role="tablist" class="tabs">{#each tabs as t}<button role="tab" aria-selected={value === t.id} class:active={value === t.id} onclick={() => (value = t.id)}>{t.label}</button>{/each}</div><style>.tabs{display:flex;gap:var(--space-1);border-bottom:1px solid var(--border)}.tabs button{background:transparent;border:none;color:var(--text-1);padding:var(--space-3) var(--space-4);border-bottom:2px solid transparent}.tabs button.active{color:var(--text-0);border-bottom-color:var(--accent)}</style>
